// generated by tools/artkit-sync.py from art-kit/examples/
const ART_EXAMPLES = {
"gear_pauldrons": "// Example 6: a chest look, drawn over the torso. P has the body joints J (J.chest, J.shR, J.shL,\n// J.pelvis, J.head ...), the axes fwd, up, sideR, the torso frame tf, and bulk (how thick the\n// armor under it is). Here: big steel shoulder plates with gold rims over a tunic.\nART.gear({\n  slot: 'chest', id: 'pauldron_tunic', name: 'PAULDRONED TUNIC',\n  draw: (r, P) => {\n    const { J, up, sideR, fwd } = P;\n    for (const [sh, s] of [[J.shR, 1], [J.shL, -1]]) {\n      const c = V.add(V.mad(sh, up, 1.2), V.mul(sideR, s * 0.8));\n      r.ell(c, [3.6, 3.2, 2.4], M.STEEL, frameAlong(fwd, V.norm(V.add(up, V.mul(sideR, s * 0.5)))), { mf: p => V.dot(V.sub(p, c), up) < -1.2 ? M.GOLD : 0 });\n    }\n  },\n});\n",
"gear_spear": "// Example 5: a weapon look. draw(r, P) runs at the hand: P.g is the grip, P.bd the direction the\n// weapon points, P.wide a direction across it, P.wf a frame [bd, wide, normal] for boxes. The game\n// already draws a short leather grip and a pommel. swing: 'light' (quick sword swings) or 'heavy'\n// (overhead chops). length: how far the tip is from the hand, for the swing smear.\nART.gear({\n  slot: 'weapon', id: 'spear', name: 'SPEAR', swing: 'light', length: 24,\n  draw: (r, P) => {\n    const { g, bd, wf } = P;\n    r.cone(V.mad(g, bd, -6), V.mad(g, bd, 20), 0.8, 0.8, M.WOOD);          // the shaft, past both ends of the hand\n    r.box(V.mad(g, bd, 23), [3, 1.4, 0.4], M.BLADE, wf);                   // the leaf-shaped head\n    r.cone(V.mad(g, bd, 26), V.mad(g, bd, 28.5), 1.2, 0.2, M.BLADE);\n    r.cyl(V.mad(g, bd, 19.5), V.mad(g, bd, 20.5), 1.1, M.CLOTH_RED);      // a red binding under the head\n  },\n});\n",
"gear_winged_helm": "// Example 4: a helm look for the hero. draw(r, P) runs where the helm is drawn and replaces the\n// whole head (so draw the face or a closed helm). P has: hd (head center), fwd, up, sideR (the\n// head's axes: forward, up, the hero's right), helmF (a frame for ell/box along those axes), eq, st, J.\nART.gear({\n  slot: 'helm', id: 'winged_helm', name: 'WINGED HELM',\n  draw: (r, P) => {\n    const { hd, fwd, up, sideR, helmF } = P;\n    const hc = V.mad(hd, up, 0.5);\n    r.ell(hc, [5.6, 5.4, 6.8], M.STEEL, helmF, { mf: p => {\n      const q = V.sub(p, hc), f2 = V.dot(q, fwd), s2 = Math.abs(V.dot(q, sideR)), z2 = V.dot(q, up);\n      if (f2 > 2.6 && Math.abs(z2) < 0.8 && s2 < 3.6) return M.DARK;   // eye slit\n      if (Math.abs(z2 - 3) < 0.6) return M.GOLD;                       // gold band\n      return 0;\n    } });\n    for (const s of [-1, 1]) {   // a white wing on each side, three feathers fanning up and back\n      for (let k = 0; k < 3; k++) {\n        const base = V.add(V.mad(hc, up, 2 + k * 0.8), V.mul(sideR, s * 5));\n        const tip = V.add(V.add(V.mad(base, up, 6 - k), V.mul(sideR, s * (3 + k))), V.mul(fwd, -2 - k * 1.5));\n        r.cone(base, tip, 1.4 - k * 0.2, 0.4, M.CLOTH_WHITE);\n      }\n    }\n  },\n});\n",
"monster_bone_captain": "// Example 1: a new monster built on an existing family (the skeleton). No new body code: only a\n// look (what it carries and wears) and its numbers. The simplest kind of submission.\nART.monster({\n  id: 'bone_captain',\n  name: 'BONE CAPTAIN',\n  family: 'skeleton',\n  look: { weapon: 'sword', shield: true, armored: true, helm: true, bone: M.OLDBONE, eye: M.FIREM, scale: 1.2 },\n  stats: { hp: 30, dmg: [4, 8], speed: 26, reach: 1.35, xp: 34, chest: 26, shadow: 8, minLevel: 2 },\n});\n",
"monster_cave_beetle": "// Example 2: a monster with a body of its own (a new family). rig(look, st) builds one pose from\n// primitives; st.clip is 'idle' (st.f 0-3), 'walk' (0-7), 'attack' (st.f = key index, st.key =\n// the key), 'hit' (0) or 'death' (0-5). Local space: +x forward, +y its right, +z up, 1 unit ~ 1 px.\nART.monster({\n  id: 'cave_beetle',\n  name: 'CAVE BEETLE',\n  newFamily: {\n    size: [64, 48, 32, 36],   // sprite box in pixels: width, height, then where its feet are\n    // the attack: rear back (a: wind-up amount), lunge, the bite (hit), recover. ms = how long each key lasts\n    swing: [{ a: 1, ms: 260, tele: true }, { a: 0.4, ms: 80, mv: 0.5 }, { a: 0, ms: 60, hit: true }, { a: 0.3, ms: 240, open: true }],\n    rig: (look, st) => {\n      const r = new Rig(), { clip, f } = st;\n      let bob = 0, lift = 0, tip = 0, legPh = 0, dead = 0;\n      if (clip === 'idle') bob = [0, -0.3, -0.5, -0.3][f % 4];\n      if (clip === 'walk') { legPh = f / 8 * Math.PI * 2; bob = Math.abs(Math.sin(legPh)) * 0.6; }\n      if (clip === 'attack') { lift = st.key.a * 3; tip = -st.key.a * 0.25; }\n      if (clip === 'hit') tip = -0.2;\n      if (clip === 'death') dead = Math.min(1, (f + 1) / 4);\n      const z = 6 + bob - dead * 3;\n      // six legs, alternating tripods while walking\n      for (let k = 0; k < 3; k++) for (const s of [-1, 1]) {\n        const x = 4 - k * 4, ph = Math.sin(legPh + (k % 2 ? 0 : Math.PI) + (s > 0 ? Math.PI : 0)) * 1.6 * (clip === 'walk' ? 1 : 0);\n        const hip = [x, s * 4, z - 1], foot = [x + ph + (dead ? 2 : 0), s * (9 + dead * 2), dead ? z : 0.5];\n        r.cone(hip, foot, 1.1, 0.7, M.CHITIN);\n      }\n      // the shell: one mass of two halves with a seam down the middle, lit from the upper left by the renderer\n      const shell = [-1, 0, z + 2 + lift * 0.3];\n      r.group(() => {\n        r.ell(shell, [9, 7, 5], M.CHITIN, null, { mf: p => Math.abs(p[1]) < 0.5 && p[2] > shell[2] ? M.DARK : 0 });\n        r.ell([7, 0, z + 1 + lift], [4, 4, 3.4], M.CHITIN);   // the head\n      });\n      // a horn that rises with the wind-up, and two glowing eyes\n      r.cone([9.5, 0, z + 2 + lift], [14 + tip * 4, 0, z + 7 + lift * 1.6], 1.6, 0.3, M.HORN);\n      for (const s of [-1, 1]) r.sph([10, s * 2.4, z + 2 + lift], 0.8, M.EYE_GRN, { noShadow: true });\n      return r;\n    },\n  },\n  stats: { hp: 20, dmg: [3, 6], speed: 34, reach: 1.3, xp: 18, chest: 12, shadow: 10, pack: true },\n});\n",
"prop_stone_lantern": "// Example 3: a prop. build(r) adds shapes for one object; it is drawn once and lit by the game.\n// size = sprite box [width, height, anchorX, anchorY]; footprint = how many tiles it blocks.\n// One tile is about 22.6 units across. yaw turns it (radians).\nART.prop({\n  id: 'stone_lantern',\n  size: [40, 56, 20, 46],\n  footprint: [1, 1],\n  yaw: 0.6,\n  build: r => {\n    r.box([0, 0, 1.5], [7, 7, 1.5], M.STONE);                       // base slab\n    r.cyl([0, 0, 3], [0, 0, 18], 3, M.STONE, { mf: p => Math.abs(p[2] - 10) < 0.6 ? M.ROCK : 0 });   // post with a carved ring\n    r.box([0, 0, 21], [5, 5, 3], M.STONE, null, { mf: p => Math.abs(p[2] - 21) < 1.6 && (Math.abs(p[0]) > 4.4 || Math.abs(p[1]) > 4.4) ? M.LAMP : 0 });   // the lamp box, glowing windows\n    r.cone([0, 0, 24], [0, 0, 31], 8, 0.6, M.ROCK);                 // a pointed roof\n  },\n});\n"
};
